// Nav bar behaviour and recipe search for The Field Kitchen. The search index
// comes from search-index.js (generated by build.py) as a plain script, so search
// also works when the site is opened straight from disk, where fetch() is blocked.
(function () {
  var MAX_RESULTS = 8;
  var nav = document.querySelector(".site-nav");
  if (!nav) return;
  // Menus only collapse once JS is here to open them again (see style.css).
  nav.classList.add("js");
  var root = nav.getAttribute("data-root") || "";

  // ---- Menus ----
  var menuToggle = nav.querySelector(".menu-toggle");
  var cuisineMenu = nav.querySelector(".cuisine-menu");
  var cuisineToggle = nav.querySelector(".cuisine-toggle");

  function setMenu(open) {
    nav.classList.toggle("menu-open", open);
    menuToggle.setAttribute("aria-expanded", String(open));
  }
  function setCuisines(open) {
    cuisineMenu.classList.toggle("open", open);
    cuisineToggle.setAttribute("aria-expanded", String(open));
  }
  menuToggle.addEventListener("click", function () { setMenu(!nav.classList.contains("menu-open")); });
  cuisineToggle.addEventListener("click", function () { setCuisines(!cuisineMenu.classList.contains("open")); });

  document.addEventListener("click", function (e) {
    if (!cuisineMenu.contains(e.target)) setCuisines(false);
    if (!nav.contains(e.target)) setMenu(false);
    if (!input.form.contains(e.target)) list.hidden = true;
  });

  function onScroll() { nav.classList.toggle("scrolled", window.scrollY > 4); }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // ---- Search ----
  var input = nav.querySelector(".search input");
  var list = nav.querySelector(".search-results");
  var index = window.FIELD_KITCHEN_INDEX || [];

  function fold(text) {
    return text.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  }

  function search(query) {
    var terms = fold(query).split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    return index
      .map(function (r) {
        var title = fold(r.title);
        var hay = title + " " + fold(r.cuisine + " " + r.category + " " + r.text);
        if (!terms.every(function (t) { return hay.indexOf(t) !== -1; })) return null;
        var score = terms.filter(function (t) { return title.indexOf(t) !== -1; }).length;
        return { r: r, score: score };
      })
      .filter(Boolean)
      .sort(function (a, b) { return b.score - a.score || a.r.title.localeCompare(b.r.title); })
      .slice(0, MAX_RESULTS)
      .map(function (m) { return m.r; });
  }

  function show(results, query) {
    list.textContent = "";
    if (!query.trim()) { list.hidden = true; return; }
    if (!results.length) {
      var empty = document.createElement("li");
      empty.className = "search-empty";
      empty.textContent = "No recipes match “" + query.trim() + "”";
      list.appendChild(empty);
    }
    results.forEach(function (r) {
      var li = document.createElement("li");
      var a = document.createElement("a");
      a.href = root + r.url;
      a.textContent = r.title;
      var where = document.createElement("span");
      where.textContent = r.cuisine + " · " + r.category;
      a.appendChild(where);
      li.appendChild(a);
      list.appendChild(li);
    });
    list.hidden = false;
  }

  input.addEventListener("input", function () { show(search(input.value), input.value); });
  input.addEventListener("focus", function () { if (input.value) show(search(input.value), input.value); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "ArrowDown") {
      var first = list.querySelector("a");
      if (first) { e.preventDefault(); first.focus(); }
    }
  });
  list.addEventListener("keydown", function (e) {
    var links = Array.prototype.slice.call(list.querySelectorAll("a"));
    var i = links.indexOf(document.activeElement);
    if (e.key === "ArrowDown" && i < links.length - 1) { e.preventDefault(); links[i + 1].focus(); }
    if (e.key === "ArrowUp") { e.preventDefault(); (i > 0 ? links[i - 1] : input).focus(); }
  });
  input.form.addEventListener("submit", function (e) {
    e.preventDefault();
    var first = list.querySelector("a");
    if (first) window.location.href = first.href;
  });

  // ---- Keyboard ----
  document.addEventListener("keydown", function (e) {
    var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if (e.key === "/" && !typing) {
      e.preventDefault();
      if (getComputedStyle(menuToggle).display !== "none") setMenu(true);
      input.focus();
    }
    if (e.key === "Escape") {
      if (document.activeElement === input || list.contains(document.activeElement)) {
        input.value = ""; show([], ""); input.blur();
      }
      setCuisines(false);
      setMenu(false);
    }
  });
})();
